class Solution:
    def longestValidParentheses(self, s: str) -> int:
        max_len = 0
        left = right = 0 # 计数器
        for ch in s:
            if ch == '(':
                left += 1
            else:
                right += 1
            if left == right:
                max_len = max(max_len, left * 2)
            elif left < right: # 不满足前缀条件
                left = right = 0

        left = right = 0 # 第二次遍历之前一定要重置!
        for ch in reversed(s):
            if ch == '(':
                left += 1
            else:
                right += 1
            if left == right:
                max_len = max(max_len, left * 2)
            elif left > right: # 不满足后缀条件
                left = right = 0

        return max_len
